window.STORY_CHAPTERS["c2a04a466776b174e"]={"id":"c2a04a466776b174e","lines":[{"uid":"talk.vc.home_time_mito_real_junior_high_school_1#originalText","id":"talk.vc.home_time_mito_real_junior_high_school_1","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"我今天有点睡眠不足。昨晚玩游戏玩得太顺了……","en":"I'm running on low sleep today. I was just making so much progress in the game last night...","ja":"今日は少し寝不足なの昨日の夜はゲームがはかどっちゃって……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_real_junior_high_school_2#originalText","id":"talk.vc.home_time_mito_real_junior_high_school_2","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"早安。看你睡眼惺忪的……呵呵。","en":"Good morning. Aww, you've got sleepy eyes.","ja":"おはよう寝ぼけまなこね……ふふ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_real_junior_high_school_3#originalText","id":"talk.vc.home_time_mito_real_junior_high_school_3","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"今天放学后有空吗？那这次也是屋顶见啰……OK吧？","en":"Do you have some time after school today? If so...meet me on the roof.","ja":"今日の放課後、時間ある？だったら、また屋上で……ね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_real_junior_high_school_4#originalText","id":"talk.vc.home_time_mito_real_junior_high_school_4","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"今天的体育课要打排球？得小心别让手指挫伤了，不然会没办法握摇杆。","en":"We have volleyball for P.E. today? I'd better not jam my fingers. Harder to handle the controller.","ja":"今日の体育はバレーボール？突き指だけは気をつけないとレバーが握れなくなっちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_real_junior_high_school_5#originalText","id":"talk.vc.home_time_mito_real_junior_high_school_5","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"肚子饿了？那我带你去吃好料。","en":"Are you hungry? Let me take you out to lunch. I know a great place.","ja":"お腹が減ったの?美味しいところに連れていってあげるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_real_junior_high_school_6#originalText","id":"talk.vc.home_time_mito_real_junior_high_school_6","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"我就算一个人吃饭也不会觉得寂寞喔。边吃饭还要边顾虑别人，饭也不会好吃吧？","en":"I don't get lonely eating by myself. Besides, eating is no fun when you have to be mindful of your company.","ja":"別に、ひとりでご飯も寂しくないわよ気を遣いながら食べたって美味しくないでしょ？"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_real_junior_high_school_7#originalText","id":"talk.vc.home_time_mito_real_junior_high_school_7","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"吃完晚餐后得念书才行。要是不维持好成绩，就没办法继续玩游戏了。","en":"I should hit the books after dinner. Unless I maintain my good GPA, I won't be allowed to play the game.","ja":"夕飯が終わったら、勉強しないと成績もキープしておかないとゲームが続けられなくなっちゃうしね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_real_junior_high_school_8#originalText","id":"talk.vc.home_time_mito_real_junior_high_school_8","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"黑暗的地方，感觉就是会有什么东西跑出来……","en":"When it's pitch-black like this, it really makes you believe in ghosts...","ja":"暗闇って何か出そうよね……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_real_junior_high_school_9#originalText","id":"talk.vc.home_time_mito_real_junior_high_school_9","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"我喜欢泡澡，不过吹头发实在很麻烦……妳也这么觉得吧？","en":"As much as I love bathing, it is so annoying drying my hair... Don't you agree?","ja":"お風呂は好きだけど、髪を乾かすのが面倒なのよね……貴方もそう思わない？"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_real_junior_high_school_10#originalText","id":"talk.vc.home_time_mito_real_junior_high_school_10","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"妳不觉得在深夜两人独处，会有种奇怪的感觉吗？就仿佛进入了别的世界一样。","en":"When it's just you and me late at night like this, it feels like we've snuck into another world...","ja":"深夜にふたりっきりでいるとまるで別の世界に入り込んだみたいな、ヘンな感じがしない？"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_real_junior_high_school_11#originalText","id":"talk.vc.home_time_mito_real_junior_high_school_11","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"困了？真拿你没办法……","en":"Sleepy? Okay, fine...","ja":"眠い?仕方ないわね……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mito_real_junior_high_school_12#originalText","id":"talk.vc.home_time_mito_real_junior_high_school_12","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"啊，已经这么晚了……不过在SAO开始前，我要多增加一点知识才行。","en":"Oh, would you look at the time... But I still need to memorize a few more things before it's SAO time.","ja":"あ、もうこんな時間……でも、SAOが始まる前に、少しでも知識を増やしておかないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_mito_real_junior_high_school_1#originalText","id":"talk.vc.home_day_mito_real_junior_high_school_1","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"一个星期又开始了。我不讨厌上学，但平日的自由时间很少实在有点讨厌。","en":"And another week begins. I don't mind Mondays, but I am a little sad to lose my free time.","ja":"また一週間のはじまりね別にイヤではないけど、平日は自由時間が少ないのがちょっとね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_mito_real_junior_high_school_2#originalText","id":"talk.vc.home_day_mito_real_junior_high_school_2","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"你好像很忙呢。其实也没差……反正你都有来见我。","en":"You seem busy. You didn't have to come... But I still appreciate it.","ja":"忙しそうね別にいいけど……こうして逢いに来てくれているし"},"kind":"dialogue"},{"uid":"talk.vc.home_day_mito_real_junior_high_school_3#originalText","id":"talk.vc.home_day_mito_real_junior_high_school_3","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"我今天应该会去电子游乐场吧。我有游戏想玩，而且要是偷懒技术会退步。","en":"I think I'll go to the arcade today. There's this game I like there and I'll lose my edge if I slack off.","ja":"私は、今日はゲーセンかなやりたいゲームがあるしサボると腕が落ちるから"},"kind":"dialogue"},{"uid":"talk.vc.home_day_mito_real_junior_high_school_4#originalText","id":"talk.vc.home_day_mito_real_junior_high_school_4","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"我想要……再跟你待一会。","en":"I just wanted to spend... a little more time with you.","ja":"もう少し……貴方と一緒にいたかったわ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_1#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_1","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"新年快乐！今年也要快乐度过一整年！我们可以主动享乐对吧？","en":"Happy New Year! Let's make it a fun one together. Having fun is one thing that's in our control, right?","ja":"あけましておめでとう今年も楽しい年にしましょう楽しむことは自発的にできるでしょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_2#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_2","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"如果要吃符合岁数的豆子，那光吃这个肚子就饱了吧。","en":"As old as I am now, eating my age in beans is enough to get me full.","ja":"年の数だけ豆を食べたらそれだけでお腹いっぱいになっちゃうわよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_3#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_3","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"来，这个送你。虽然我一直以来多半是收下巧克力的那一方……","en":"Here. Chocolate. Though I must say, I'm more used to being on the receiving end.","ja":"はい、これ昔から、チョコはもらう機会の方が多かったけれど……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_4#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_4","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"关于女儿节娃娃的回忆吗？我小时候总觉得「那衣服看起来好难活动」。","en":"I remember Hinamatsuri dolls. When I was little, I thought their clothes looked very uncomfortable.","ja":"雛人形の思い出ね子供心に「動きづらそうな服」って思っていたわ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_5#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_5","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"……要给我吗？谢谢……","en":"Is that for me? Thanks...","ja":"……くれるの?ありがとう……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_6#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_6","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"我没办法骗人的。……骗你的。","en":"I cannot tell a lie... Yeah, that's a lie.","ja":"私、嘘はつけないの……嘘よ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_7#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_7","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"即使放长假，也会在玩游戏跟念书当中一下就结束了。当学生就是这么一回事吧。","en":"Even a long vacation flashes by when you fill it with studying and gaming. That's student life.","ja":"長いお休みも、ゲームと勉強で気がついたら終わってるのよね学生のうちはしょうがないか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_8#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_8","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"地上都是烂泥巴，没办法好好打怪练等。真是令人忧郁的季节……","en":"The ground's too marshy to plant my feet for a good shot. Don't you just love rainy season?","ja":"足下がぬかるんでうまく狩れない憂鬱なシーズンね……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_9#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_9","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"织女是天琴座α，牛郎是天鹰座α，挡在他们之间的河就是银河。","en":"Orihime is Vega, Hikoboshi is Altair, and \"Heaven's river\" is the Milky Way.","ja":"織姫がベガ彦星はアルタイル天の川はミルキーウェイよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_10#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_10","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"哪一天从考试和念书解脱后，我们俩一起悠悠哉哉地去海边旅行吧。","en":"Once we're free from studying for entrance exams, let's take a nice trip to the beach.","ja":"いつか、受験とか勉強とかから解放されたら、ふたりでゆっくり海辺に旅行しましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_11#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_11","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"夏天的尾声总是让人感到寂寞呢。","en":"The end of summer always makes me feel a bit melancholy.","ja":"夏の終わりって物寂しいわよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_12#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_12","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"你觉得月亮的纹路看起来像什么？我一点都不觉得像兔子。","en":"What do you think the moon craters look like? 'Cause I just don't see a rabbit.","ja":"月の模様って何に見える?私はウサギに見えないのよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_13#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_13","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"近年来的万圣节扮装，越来越常看到有人扮成游戏角色了呢。","en":"I've noticed that every Halloween, more and more people dress up as video game characters.","ja":"最近は、ハロウィンの仮装でゲームのキャラを見かけることも増えてきたわね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mito_real_junior_high_school_15#originalText","id":"talk.vc.home_event_mito_real_junior_high_school_15","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"这样的日子，你跟我在一起没关系吗？","en":"Are you sure you're okay with spending a special day like this with me?","ja":"こんな日に、私と一緒にいて貴方はそれでいいの……?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_mito_real_junior_high_school_1#originalText","id":"talk.vc.home_season_mito_real_junior_high_school_1","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"游戏和学习的内容每年都在变，但樱花始终不变，每年都会绽放呢。","en":"My games and studies change every year...but the cherry blossoms never stop blooming in the spring.","ja":"ゲームも勉強の内容も毎年変わっていくけど、桜の花って毎年変わらずに咲くのよね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_mito_real_junior_high_school_2#originalText","id":"talk.vc.home_season_mito_real_junior_high_school_2","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"我讨厌炎热，因为手汗会让掌心好滑。","en":"I hate hot summer days. Too much slippery sweat.","ja":"暑いのは嫌いよ手汗で滑るから"},"kind":"dialogue"},{"uid":"talk.vc.home_season_mito_real_junior_high_school_3#originalText","id":"talk.vc.home_season_mito_real_junior_high_school_3","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"镰刀原本是在收获时使用的农具吧……啊，我因为最近玩的游戏，所以有点在意。","en":"Sickles were originally used in the grain harvest, right? Oh, it came up in a game I'm playing.","ja":"鎌って、元々収穫期に使われた農具なのよね……あ、今やってるゲームで、ちょっと気になって"},"kind":"dialogue"},{"uid":"talk.vc.home_season_mito_real_junior_high_school_4#originalText","id":"talk.vc.home_season_mito_real_junior_high_school_4","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"我讨厌寒冷，因为手指会冻僵。","en":"I hate the cold. My fingers get all stiff.","ja":"寒いのは嫌いよ指がかじかむから"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_mito_real_junior_high_school_1#originalText","id":"talk.vc.home_etc_mito_real_junior_high_school_1","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"达成使命了，你很行嘛。","en":"Mission accomplished. Not too shabby.","ja":"ミッション達成ねやるじゃないの"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_mito_real_junior_high_school_2#originalText","id":"talk.vc.home_etc_mito_real_junior_high_school_2","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"有礼物送来了。不要放到忘记，早点去看看吧。","en":"You've got a present. Open it before you forget.","ja":"プレゼントが届いているわ忘れないうちに確認よ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_mito_real_junior_high_school_3#originalText","id":"talk.vc.home_etc_mito_real_junior_high_school_3","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"好像有新任务呢。来，我们走吧。","en":"I hear a new Quest just came in. Come on, let's check it out.","ja":"新しいクエストがあるみたいねほら、行きましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_2#originalText","id":"talk.vc.home_bd_alice_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你记得我的生日啊。……我好开心。","en":"You remembered my birthday? Ⅰ am...very honored.","ja":"私の誕生日、なのですか?そうなのですね……うれしいです、とても"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_3#originalText","id":"talk.vc.home_bd_alice_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天是桐人的生日吗？虽然我觉得没什么必要，不过……姑且还是准备一下好了。","en":"It's Kirito's birthday? I doubt he needs a present, but I'll have one ready...just in case.","ja":"キリトの誕生日ですか必要はないと思いますが一応……祝いの用意はしましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_4#originalText","id":"talk.vc.home_bd_alice_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天是尤吉欧的生日呢。我们一起去祝贺他吧。","en":"It's Eugeo's birthday. Let's go give him some good cheer.","ja":"ユージオの誕生日ですね一緒に祝いに行きましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_6#originalText","id":"talk.vc.home_bd_alice_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"亚丝娜的生日……她会跟桐人两个人一起庆祝吧？","en":"Asuna's birthday... She'll probably want to celebrate alone with Kirito.","ja":"アスナの誕生日……キリトとふたりでお祝いをするのでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_7#originalText","id":"talk.vc.home_bd_alice_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天是莉法阁下的生日呢。如果是她，收到剑作为礼物肯定会感到高兴。","en":"It's Leafa's birthday. I know she would love to receive a sword as a gift.","ja":"リーファの誕生日ですね彼女なら、きっと剣の贈り物を喜んでくれるでしょう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_8#originalText","id":"talk.vc.home_bd_alice_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"诗乃阁下……在她的生日，果然还是送一把弓比较好吗？","en":"For Sinon's birthday... I suppose a bow would be the best gift.","ja":"シノン……誕生日にはやはり弓をお贈りするのがいいでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_11#originalText","id":"talk.vc.home_bd_alice_11","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天是罗妮耶的生日呢。她喜欢蜂蜜派对吧，我们一起去买吧。","en":"It's Ronie's birthday. Her favorite dessert is honey pies, correct? Let's go buy her some.","ja":"ロニエさんの誕生日ですか彼女の好物は蜂蜜パイでしたね一緒に買って行きましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_12#originalText","id":"talk.vc.home_bd_alice_12","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天是缇洁的生日啊？大家一起帮她庆祝肯定很不错。","en":"Tiese's birthday, you say? A party with all her friends would probably be best.","ja":"ティーゼさんの誕生日ですかみんなでお祝いするのがきっといいのでしょうね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_sleeping_5#originalText","id":"talk.vc.home_bd_alice_uw_sleeping_5","speaker":{"ja":"アリス"},"text":{"ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_2#originalText","id":"talk.vc.home_bd_asuna_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"谢谢你。能收到你的祝福，是最让我开心的事。","en":"Thanks. Celebrating with you is the best gift of all.","ja":"ありがとう君に祝ってもらえるのが一番うれしいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_3#originalText","id":"talk.vc.home_bd_asuna_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呵呵，这已经是第几次啦？希望今后也可以一直一起过生日。","en":"Hehe. How many times is it now? I hope we get to spend every birthday together from now on!","ja":"ふふ、もう何回目かなこれからもずーっと、誕生日には一緒に過ごせるといいね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_5#originalText","id":"talk.vc.home_bd_asuna_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天是爱丽丝的生日吧。你知道她喜欢什么吗？","en":"Today is Alice's birthday? Do you know what she likes?","ja":"今日はアリスさんの誕生日なのね好きなものとか、知ってる? "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_7#originalText","id":"talk.vc.home_bd_asuna_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天是莉法的生日！你应该有好好准备礼物吧？","en":"It's Leafa's birthday! You have a present for her, right?","ja":"リーファちゃんの誕生日だね! ちゃんとプレゼント用意してるんでしょうね? "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_8#originalText","id":"talk.vc.home_bd_asuna_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我们来办小诗诗的庆生会吧。把大家都找去《Dicey Cafe》！","en":"Let's throw Shino-non a birthday party. We'll have the gang over at the Dicey Café.","ja":"シノのんの誕生日会、やろうよ《ダイシー・カフェ》にみんなで集まって! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_9#originalText","id":"talk.vc.home_bd_asuna_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"因为今天是有纪的生日，所以晚上预定要跟《沉睡骑士》所有人一起举办派对。","en":"Since it's Yuuki's birthday today, the Sleeping Knights and I are throwing her a night party.","ja":"今日はユウキの誕生日だから《スリーピング・ナイツ》のみんなと夜パーティーをする予定なの"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_11#originalText","id":"talk.vc.home_bd_asuna_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"罗妮耶是今天生日啊？你要送她什么呢？","en":"Oh, it's Ronie's birthday today? What did you get her?","ja":"ロニエさん、今日誕生日なんだどんなものを贈るの? "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_12#originalText","id":"talk.vc.home_bd_asuna_12","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"缇洁的生日是今天呢。我们去帮她庆祝吧。","en":"It's Tiese's birthday today, eh? Let's throw her a party.","ja":"ティーゼさんは今日が誕生日なんだねお祝いしに行こうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_14#originalText","id":"talk.vc.home_bd_asuna_14","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天不是莉兹的生日吗？所以我想，偶尔就我们两个女生庆祝也不错。","en":"It's Liz's birthday, right? I thought a party with just us girls would be great.","ja":"今日はリズの誕生日でしょたまには、女ふたりだけでお祝いもいいかなって"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_15#originalText","id":"talk.vc.home_bd_asuna_15","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天是西莉卡的生日喔。来，我们一起去帮她庆祝吧！","en":"It's Silica's birthday today. Come on, let's go wish her a happy birthday!","ja":"今日はシリカちゃんの誕生日だよほら、一緒にお祝いに行こう? "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_3#originalText","id":"talk.vc.home_bd_edith_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天是那小子的生日啊。你该不会很在意吧？","en":"It's that boy's birthday? Wait, do you have a thing for him?","ja":"あの坊やの誕生日かもしかして、気になってるの? "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_4#originalText","id":"talk.vc.home_bd_edith_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"那位拿蓝剑的男孩，原来是今天生日啊。你有要送什么吗？","en":"The boy with the blue rose sword is having a birthday today. Are you going to get him a gift?","ja":"あの青い剣の男の子今日が誕生日なんだなにか贈り物するの? "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_5#originalText","id":"talk.vc.home_bd_edith_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天是爱丽丝的生日，得盛大庆祝才行！","en":"Since today is Alice's birthday, we need to celebrate!","ja":"今日はアリスの何かの記念日なんだって! よくわからないけど盛大にお祝いしないと! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_6#originalText","id":"talk.vc.home_bd_edith_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"既然是亚丝娜大人的生日，那就是整个人界的祭典了吧。","en":"The Lady Asuna's birthday? Why, that is surely a huge festival for the Human Realm.","ja":"アスナのお誕生日だったらそれはもう人界のお祭りだよね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_7#originalText","id":"talk.vc.home_bd_edith_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天是绿之剑士大人的生日……你觉得她会喜欢什么东西？","en":"It's the green swordswoman's birthday? Would you tell me what sort of gift she would like?","ja":"リーファの誕生日……どのようなものが喜ばれると思う? "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_8#originalText","id":"talk.vc.home_bd_edith_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"诗乃大人的生日……就当作是索鲁斯大人的祭典，大家一起庆祝吧！","en":"It's Sinon's birthday... Let's all celebrate the way we do at the Solus festival!","ja":"シノンの誕生日……ソルス様のお祭りとしてみんなでお祝いしよう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_11#originalText","id":"talk.vc.home_bd_edith_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天是罗妮耶的生日呢。把那位黑发男孩带去的话，不知道她会不会高兴？","en":"So it's Ronie's birthday today. I know a great gift for her: that black-haired boy.","ja":"ロニエ、今日が誕生日なんだあの黒髪の男の子を連れてってあげたら喜ぶかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_12#originalText","id":"talk.vc.home_bd_edith_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天是缇洁的生日啊。你要是帮她庆祝，她一定会很开心的。","en":"So it's Tiese's birthday today. I'm sure she would be honored if you threw her a party.","ja":"ティーゼの誕生日なのねきっとあなたがお祝いしてあげると喜ぶと思うよ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_eugeo_2#originalText","id":"talk.vc.home_bd_eugeo_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"咦，生日？对喔，没错……我自己都忘了。","en":"Huh? It's my birthday? Oh. You're right... I can't believe I forgot.","ja":"えっ、誕生日? そっか、そうだったね……自分でも忘れていたよ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_eugeo_3#originalText","id":"talk.vc.home_bd_eugeo_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天是桐人的生日吧。今天我来请客，想吃什么就尽管点吧。","en":"Today is Kirito's birthday! Order anything you'd like today. My treat!","ja":"今日、キリトの誕生日だったね今日は僕が奢るからなんでも好きなものを頼みなよ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_eugeo_5#originalText","id":"talk.vc.home_bd_eugeo_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"爱丽丝的生日……即便知道见不到她，我还是每年都会准备礼物。","en":"Alice's birthday... Even though I know I won't see her, I always plan for it every year.","ja":"アリスの誕生日……会えないってわかってても毎年準備してたものがあるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_eugeo_11#originalText","id":"talk.vc.home_bd_eugeo_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"听说今天是罗妮耶的生日。如果你去见她，她一定会很开心的。","en":"I heard that today is Ronie's birthday. I think she'd love it if you went to see her.","ja":"今日はロニエの誕生日だって行ってあげたら、きっと喜ぶと思うよ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_eugeo_12#originalText","id":"talk.vc.home_bd_eugeo_12","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天是缇洁的生日啊……我是有准备礼物，不过直接交给她好吗……","en":"Tiese's birthday, huh... I did get her a gift, but I wonder if I should hand it to her in person.","ja":"ティーゼの誕生日か……贈り物を用意したけど直接渡してもいいかな……"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_2#originalText","id":"talk.vc.home_bd_kirito_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"你记得我的生日啊？谢谢你！今后也请多多指教喔。","en":"You remembered my birthday? Thanks! You're a great friend.","ja":"誕生日覚えててくれたのかありがとう!これからもよろしくな"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_4#originalText","id":"talk.vc.home_bd_kirito_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"听说今天是尤吉欧的生日。来请他吃些好料好了！","en":"It's Eugeo's birthday today. Maybe I should treat him to a special dinner or something.","ja":"今日はユージオの誕生日なんだってななんかうまいもんでもご馳走してやるかな"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_5#originalText","id":"talk.vc.home_bd_kirito_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天好像是爱丽丝的生日。尤吉欧有说要庆祝，但不知道她会是什么反应……","en":"I hear it's Alice's birthday today. Eugeo said he's doing something special for her. I wonder how she'll react...","ja":"今日はアリスの誕生日らしいなユージオはお祝いするって言ってたけどどんな反応するんだろう……"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_6#originalText","id":"talk.vc.home_bd_kirito_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是亚丝娜的生日啊……必须跟结衣一起庆祝才行呢！","en":"It's Asuna's birthday today. Yui and I should do something special for her.","ja":"今日はアスナの誕生日か……ユイと一緒にお祝いしなきゃな!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_7#originalText","id":"talk.vc.home_bd_kirito_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是小直的生日吧。她好像说过，有想要什么东西……","en":"It's Sugu's birthday today. I think I remember her talking about something she wanted...","ja":"今日はスグの誕生日だななんか欲しいものあるって言ってたような……"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_8#originalText","id":"talk.vc.home_bd_kirito_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天好像要在现实那边，举办诗乃的生日派对喔。","en":"We're throwing Sinon a birthday party IRL today.","ja":"今日はリアルでシノンの誕生日パーティをやるらしいぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_9#originalText","id":"talk.vc.home_bd_kirito_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是有纪的生日啊。大家一起替她庆祝吧。","en":"It's Yuuki's birthday today. We should all throw her a party.","ja":"今日はユウキの誕生日かみんなでお祝いするか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_11#originalText","id":"talk.vc.home_bd_kirito_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是罗妮耶的生日吧。本想进行特别训练当作庆祝，却被尤吉欧骂了……嗯～该选什么当礼物呢？","en":"It's Ronie's birthday today. When I told Eugeo I was going as a present, he yelled at me. Hmmm...maybe I should give her a real present instead.","ja":"ロニエの誕生日祝いに特別稽古をつけようとしたらユージオに怒られたんだよなぁ……何をプレゼントしよう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_12#originalText","id":"talk.vc.home_bd_kirito_12","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是缇洁的生日。她是说尤吉欧送什么她都开心啦～我也送个跳鹿亭的私房派好了。","en":"It's Tiese's birthday today. Eugeo said she'd be flattered to get a present from me, no matter what it is... I think I'll get her a special pie, too.","ja":"今日はティーゼの誕生日だ跳ね鹿亭のとっておきのパイをプレゼントしよう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_14#originalText","id":"talk.vc.home_bd_kirito_14","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是莉兹的生日啊。西莉卡和亚丝娜好像企划着什么喔。","en":"It's Liz's birthday today... I hear Silica and Asuna have something special planned.","ja":"今日はリズの誕生日かシリカとアスナが何か企画してるらしいぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_15#originalText","id":"talk.vc.home_bd_kirito_15","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是西莉卡的生日啊。这么说来，她到底几岁了啊？","en":"It's Silica's birthday today. Come to think of it, how old is she?","ja":"今日はシリカの誕生日かそういえば何歳になったんだろう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_2#originalText","id":"talk.vc.home_bd_leafa_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"嘿嘿，谢谢你帮我庆生。我超开心的呢！","en":"Hehehe, thanks for the birthday wishes. That was so sweet!","ja":"えへへ、誕生日お祝いしてくれてありがとうすごくうれしいよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_3#originalText","id":"talk.vc.home_bd_leafa_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天是哥哥的生日……不知道庆生派对办不办得成？","en":"Today is Kirito's birthday... Maybe I should throw him a party.","ja":"今日はお兄ちゃんの誕生日……お祝いパーティー、できるかな"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_5#originalText","id":"talk.vc.home_bd_leafa_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天是爱丽丝的生日？那大家一起帮她庆祝吧！","en":"It's Alice's birthday? Well, we should all celebrate!","ja":"アリスさんのお誕生日? だったら、みんなでお祝いしようよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_6#originalText","id":"talk.vc.home_bd_leafa_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我们也想帮亚丝娜小姐庆生呢。","en":"It's Asuna's birthday. We should do something special for her, too.","ja":"アスナさんの誕生日あたしたちもお祝いしたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_8#originalText","id":"talk.vc.home_bd_leafa_8","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天是诗乃的生日。嗯～该送什么礼物好呢？","en":"It's Sinon's birthday today. Hmm...I wonder what I should get her.","ja":"シノンさんのお誕生日なんだうーん、プレゼント何がいいだろう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_9#originalText","id":"talk.vc.home_bd_leafa_9","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"大家要帮有纪庆生！我会带花过去的。","en":"We're all throwing a birthday party for Yuuki, right? I'm bringing the flowers.","ja":"ユウキさんのお誕生日みんなでお祝いするんだよね! あたしは、お花を持っていくの"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_11#originalText","id":"talk.vc.home_bd_leafa_11","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天是罗妮耶的生日，我打算烤一份加了蜂蜜的派。","en":"I was thinking of baking a pie with honey as a sweetener for Ronie's birthday","ja":"ロニエちゃんの誕生日、蜂蜜を使ったパイを焼いてみようと思うんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_12#originalText","id":"talk.vc.home_bd_leafa_12","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天是缇洁的生日嘛，我去参加女生的聚会啰。男生不准来！","en":"We're having a girls' night out for Tiese's birthday. No boys allowed!","ja":"ティーゼちゃんが誕生日だから女子会してくるね男子は来るの禁止! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_14#originalText","id":"talk.vc.home_bd_leafa_14","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天是莉兹的生日喔。大家要帮她庆祝，你也一起来吧！","en":"It's Liz's birthday today. Come on, let's go wish her a happy birthday.","ja":"リズさんがお誕生日だよほら、みんなでお祝いするから一緒に行こう! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_15#originalText","id":"talk.vc.home_bd_leafa_15","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"西莉卡的生日我打算送她衣服。一定会很适合她的！","en":"I was thinking of getting Silica a dress for her birthday. I'm sure she'll look adorable!","ja":"シリカちゃんの誕生日に可愛いお洋服を贈ろうと思うんだきっと似合うよね! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_lisbeth_2#originalText","id":"talk.vc.home_bd_lisbeth_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"咦，你记得我的生日吗？……谢谢你。","en":"You remembered my birthday? ...Thanks!","ja":"え、誕生日? 覚えててくれたの? ……ありがと"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_lisbeth_3#originalText","id":"talk.vc.home_bd_lisbeth_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"今天是桐人的生日呢。没办法，我还是去帮他庆祝好了。","en":"It's Kirito's birthday today. Oh well, I guess I might as well get him a present.","ja":"今日はキリトの誕生日よねしょうがないから、お祝いしてあげようかな"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_lisbeth_5#originalText","id":"talk.vc.home_bd_lisbeth_5","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"今天是爱丽丝的生日啊？剑她已经有了，所以送防具相关的比较好吗……","en":"Today is Alice's birthday? Since she already has a sword, maybe she'd like some defensive gear?","ja":"アリス、今日がお誕生日か剣は持ってるから、なにか防具関係がいいかなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_lisbeth_6#originalText","id":"talk.vc.home_bd_lisbeth_6","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"亚丝娜的生日，你有做好准备吗？我是可以陪你商量啦。","en":"Do you have plans for Asuna's birthday yet? I can help if you need any ideas.","ja":"アスナの誕生日、ちゃんと準備してる? 相談に乗ってあげてもいいけど"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_lisbeth_7#originalText","id":"talk.vc.home_bd_lisbeth_7","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"莉法的生日，方便的话要不要大家一起帮她庆祝？","en":"Wanna throw Leafa a birthday party with the gang?","ja":"リーファの誕生日、よかったらみんなでお祝いしてあげない? "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_lisbeth_8#originalText","id":"talk.vc.home_bd_lisbeth_8","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"诗乃会想要什么东西啊？得准备她的生日礼物才行。","en":"What would Sinon like for her birthday? I need to get her something.","ja":"シノンって、どんなものがほしいんだろう? 誕生日プレゼント、用意しないと"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_lisbeth_9#originalText","id":"talk.vc.home_bd_lisbeth_9","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"亚丝娜说要帮有纪办庆生会，大家一起帮她庆祝吧！","en":"Asuna is throwing Yuuki a birthday party. We should all go!","ja":"アスナがユウキの誕生会をやるんだってみんなでお祝いしてあげましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_lisbeth_15#originalText","id":"talk.vc.home_bd_lisbeth_15","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"今天是西莉卡的生日吧。我当然有准备礼物啰！","en":"It's Silica's birthday! And of course I got her a present already.","ja":"今日はシリカの誕生日よねもちろん、プレゼントは用意してあるわ! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_mary_13#originalText","id":"talk.vc.home_bd_mary_13","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"呵呵，今天吃大餐喔！毕竟是姊姊的生日啊。要多吃点喔，姊姊！","en":"Ohh, we're gonna have a big feast today! Hehehe. Well, it's your birthday, so eat up, Sister!","ja":"ふふ、今日はごちそうだよ!だってお姉ちゃんの誕生日だもんたくさん食べてね、お姉ちゃん!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_2#originalText","id":"talk.vc.home_bd_ronye_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"您记得我的生日吗？我好开心喔，学长！","en":"You remembered my birthday? I am very honored, sir!","ja":"私の誕生日、覚えていてくれたのですか? うれしいです、先輩! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_3#originalText","id":"talk.vc.home_bd_ronye_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"生日快乐，桐人学长！请你……收下这个。","en":"I hope Kirito has a wonderful birthday! Look...I got him a present.","ja":"おめでとうございますキリト先輩!これ……受け取ってください"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_4#originalText","id":"talk.vc.home_bd_ronye_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"尤吉欧学长今天生日吗！？这么一来，得帮他庆祝才行！","en":"It's Eugeo's birthday?! We need to celebrate!","ja":"ユージオ先輩、今日お誕生日なんですか!?でしたら、お祝いしないと! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_5#originalText","id":"talk.vc.home_bd_ronye_5","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"今天是爱丽丝大人的生日呢。那副身影……我果然还是很尊敬她。","en":"Today is Lady Alice's birthday. I do admire how majestic she is!","ja":"今日はアリスさまのお誕生日なんですね。あのお姿……やっぱり尊敬してしまいます"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_6#originalText","id":"talk.vc.home_bd_ronye_6","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"亚丝娜大人也有生日呀……不，我只是以为史提西亚大人的化身应该算是神明吧……","en":"The goddess Asuna also has a birthday? Oh, that is, if Stacia had a human incarnation, I imagined she would be like Asuna.","ja":"アスナさんにもお誕生日が……いえ、ステイシア様の化身であれば神様なのかな、と思いまして……"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_7#originalText","id":"talk.vc.home_bd_ronye_7","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"绿之剑士大人的生日……她是学长的家人没错吧？是怎么样的一个人呢？","en":"The green swordswoman's birthday... She's related to you, isn't she? What is she like?","ja":"リーファさんのお誕生日……先輩のご家族なんですよねどのような方、なのでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_8#originalText","id":"talk.vc.home_bd_ronye_8","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"今天是诗乃大人的生日吧。我觉得诗乃大人的武器……真的很不可思议。","en":"Today is Lady Sinon's birthday, I hear. Her weapon is very...mystical.","ja":"今日はシノンさんのお誕生日ですね。シノンさんの武器……とても不思議な感じがしました"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_12#originalText","id":"talk.vc.home_bd_ronye_12","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长，今天是缇洁的生日！大家一起悄悄庆祝吧！","en":"It's Tiese's birthday today, sir! Want to throw her a surprise birthday party?","ja":"先輩、今日はティーゼの誕生日です! みんなでこっそりお祝いしませんか?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_silica_2#originalText","id":"talk.vc.home_bd_silica_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"你愿意帮我庆生吗？……非常谢谢你！我太感动了，眼泪都……","en":"Huh? You have a gift for me, too? Oh...thank you so much! I could just cry...","ja":"誕生日、お祝いしてくれるんですか?……ありがとうございます! あたし、感激しちゃって涙が……"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_silica_3#originalText","id":"talk.vc.home_bd_silica_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"今天是桐人哥的生日……必须确实把礼物送到他手上才行！","en":"It's Kirito's birthday... I need to be brave and give him a present!","ja":"今日はキリトさんのお誕生日……ちゃんとプレゼント、渡さなきゃ!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_silica_5#originalText","id":"talk.vc.home_bd_silica_5","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"今天是爱丽丝小姐的生日对吧。嗯……我想送她给雨缘用的蝴蝶结之类的礼物。","en":"It's Alice's birthday today, right? Hmm... I was thinking a ribbon for Amayori? That might be a good present.","ja":"アリスさん、今日お誕生日ですよねええと……雨縁ちゃんのリボンとかプレゼントしようかなって思います"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_silica_6#originalText","id":"talk.vc.home_bd_silica_6","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"今天是亚丝娜姊姊的生日。礼物我已经准备好了！","en":"It's Asuna's birthday! And I got her a present!","ja":"今日はアスナさんの誕生日ですプレゼント、用意してきました! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_silica_7#originalText","id":"talk.vc.home_bd_silica_7","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"今天是莉法姊姊的生日呢。该送什么礼物好呢？","en":"It's Leafa's birthday today. Hmm...I wonder what I should get her.","ja":"リーファさん、お誕生日ですねプレゼント、何がいいでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_silica_8#originalText","id":"talk.vc.home_bd_silica_8","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"在诗乃姊姊生日当天，我们打算要举办派对……你要不要一起去呢？","en":"People are talking about throwing a party for Sinon. Want to go with me?","ja":"シノンさんの誕生日に、パーティーをしようってお話があって……一緒に行きませんか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_silica_9#originalText","id":"talk.vc.home_bd_silica_9","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"有纪姊姊的庆生会是吗？我也可以去吗？","en":"A birthday party for Yuuki? Do you think I'm invited?","ja":"ユウキさんのお誕生会ですか? あたしも行って大丈夫でしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_silica_14#originalText","id":"talk.vc.home_bd_silica_14","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"今天是莉兹姊姊的生日！我要送她可爱的饰品喔～","en":"It's Liz's birthday! I'm giving her some cute jewelry.","ja":"今日はリズさんのお誕生日です! かわいいアクセサリーをプレゼントするんですよ～"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_2#originalText","id":"talk.vc.home_bd_sinon_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你记得我的生日啊。……谢谢，我非常开心。","en":"You remembered my birthday... Thanks. That's so sweet of you.","ja":"誕生日、覚えててくれたのね……ありがとうすごく、うれしい"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_3#originalText","id":"talk.vc.home_bd_sinon_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"今天是桐人的生日呢。我也想要帮他庆祝……得准备礼物才行。","en":"It's Kirito's birthday today. I want to do something special for him, so I'd better get him a present.","ja":"キリトの誕生日ね私だって、お祝いしたいから……プレゼント、用意しなきゃ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_5#originalText","id":"talk.vc.home_bd_sinon_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"今天是爱丽丝的生日呢。她应该不想要吃的……就送她女孩子气的衣服好了。","en":"It's Alice's birthday today. She probably doesn't want something edible... Maybe a cute dress?","ja":"今日はアリスの誕生日なのね食べ物はいらないだろうし……女の子らしい服、とかはどうかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_6#originalText","id":"talk.vc.home_bd_sinon_6","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"今天是亚丝娜的生日，所以我就出门啰。偶尔就两个人也没差吧。","en":"Today is Asuna's birthday, so I'm going out for a bit. Or you can come with me, whatever.","ja":"今日はアスナの誕生日だからちょっと行ってくる。別にいいでしょふたりきりで行っても"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_7#originalText","id":"talk.vc.home_bd_sinon_7","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"原来今天是莉法的生日。她有想要的东西吗？例如剑道道具之类的。","en":"Oh, it's Leafa's birthday. Has she mentioned anything she wants? Like kendo gear?","ja":"リーファ、誕生日なんだ剣道の道具とか、なにか欲しがっていたものあった? "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_9#originalText","id":"talk.vc.home_bd_sinon_9","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你会去有纪的庆生会吧？我要先过去布置，待会见啰。","en":"You're going to Yuuki's birthday party, right? I'll see you later. I'm going early to help decorate.","ja":"ユウキの誕生日会、行くんでしょ?私は飾り付けをしに先に行くからまたあとでね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_11#originalText","id":"talk.vc.home_bd_sinon_11","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"今天是罗妮耶的生日啊。大家一起庆祝吧。","en":"It's Ronie's birthday? We should throw her a party.","ja":"ロニエが誕生日なのねみんなでお祝いしましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_12#originalText","id":"talk.vc.home_bd_sinon_12","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"缇洁的生日啊。如果她可以不要叫我索鲁斯大人，我就能够以更轻松的态度去找她了。","en":"If you didn't invite Solus to Tiese's birthday party, I'd feel much more comfortable going.","ja":"ティーゼの誕生日、ソルス様って呼ぶのをやめてくれたらもっと気軽に行けるんだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_14#originalText","id":"talk.vc.home_bd_sinon_14","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你为莉兹的庆生会选了什么礼物啊？","en":"What did you get Liz for her birthday?","ja":"リズの誕生日会プレゼントは何を選んだの? "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sinon_15#originalText","id":"talk.vc.home_bd_sinon_15","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"西莉卡生日时，我打算送演唱会门票。她好像喜欢这类的东西。","en":"I'm getting Silica concert tickets for her birthday. I think she'd like that.","ja":"シリカの誕生日はコンサートチケットを贈るつもりそういうの好きみたいだから"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sortiliena_3#originalText","id":"talk.vc.home_bd_sortiliena_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"是桐人的生日啊。那今天就特别带他上街吧。","en":"It's Kirito's birthday? Then I'll take him to the city as a special treat.","ja":"キリトの誕生日かなら今日は特別に、街へ連れて行ってやるか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sortiliena_4#originalText","id":"talk.vc.home_bd_sortiliena_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"今天是尤吉欧修剑士的生日？那么，我就跟哥鲁哥罗索同学一起帮他庆祝吧。","en":"It's Eugeo's birthday? Then Golgorosso and I shall throw him a party!","ja":"ユージオの誕生日? ならば、ゴルゴロッソ殿と祝ってやるとしよう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sortiliena_5#originalText","id":"talk.vc.home_bd_sortiliena_5","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"今天是爱丽丝大人的生日啊……不知道她会喜欢什么礼物呢？","en":"It's Lady Alice's birthday... What sort of gift would please her?","ja":"アリス様のお誕生日か……どのような贈り物ならば喜んでいただけるだろうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sortiliena_6#originalText","id":"talk.vc.home_bd_sortiliena_6","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"亚丝娜大人的生日……如果要送礼给那位大人，还是剑之类的比较合适吧……","en":"It's Lady Asuna's birthday... I suppose a woman of her caliber would want a sword as a gift.","ja":"アスナさんの誕生日……あの方ならば、やはり剣などがよいだろうか……"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sortiliena_7#originalText","id":"talk.vc.home_bd_sortiliena_7","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"今天是绿之剑士大人的生日啊？你愿意告诉我，她是怎样的一个人吗？","en":"It's the green swordswoman's birthday? Would you tell me what sort of person she is?","ja":"リーファさんの誕生日かどのような方なのか教えてくれないか? "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sortiliena_8#originalText","id":"talk.vc.home_bd_sortiliena_8","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"今天是索鲁斯大人……更正，诗乃大人的生日啊。那我就奉上一把弓吧。","en":"Today is Solus...I mean, Sinon's birthday? I know. I'll get her a bow.","ja":"今日はシノンさんの誕生日かならば弓を贈らせていただこう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sortiliena_11#originalText","id":"talk.vc.home_bd_sortiliena_11","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"罗妮耶的生日……既然如此，我们共同送她礼物如何？","en":"Ronie's birthday, huh... How about we get her a present together?","ja":"ロニエの誕生日……ならば、一緒にお祝いの品を贈るのはどうだ? "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sortiliena_12#originalText","id":"talk.vc.home_bd_sortiliena_12","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"缇洁的生日就在今天啊。那么也叫上尤吉欧，大家一起举办庆生会吧。","en":"So, today is Tiese's birthday... Let's invite Eugeo and the others, and throw her a dinner party.","ja":"ティーゼの誕生日は今日かならばユージオも呼んで皆で祝の宴を開こう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_suguha_2#originalText","id":"talk.vc.home_bd_suguha_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"嘿嘿，谢谢你帮我庆生。我超开心的呢！","en":"Hehehe, thanks for the birthday wishes. That was so sweet!","ja":"えへへ、誕生日お祝いしてくれてありがとうすごくうれしいよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_suguha_3#originalText","id":"talk.vc.home_bd_suguha_3","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"今天是哥哥的生日……不知道庆生派对办不办得成？","en":"Today is Kirito's birthday... Maybe I should throw him a party.","ja":"今日はお兄ちゃんの誕生日……お祝いパーティー、できるかな"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_suguha_5#originalText","id":"talk.vc.home_bd_suguha_5","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"今天是爱丽丝的生日？那大家一起帮她庆祝吧！","en":"It's Alice's birthday? Well, we should all celebrate!","ja":"アリスさんのお誕生日? だったら、みんなでお祝いしようよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_suguha_6#originalText","id":"talk.vc.home_bd_suguha_6","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"我们也想帮亚丝娜小姐庆生呢。","en":"It's Asuna's birthday. We should do something special for her, too.","ja":"アスナさんの誕生日あたしたちもお祝いしたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_suguha_8#originalText","id":"talk.vc.home_bd_suguha_8","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"今天是诗乃的生日。嗯～该送什么礼物好呢？","en":"It's Sinon's birthday today. Hmm...I wonder what I should get her.","ja":"シノンさんのお誕生日なんだうーん、プレゼント何がいいだろう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_suguha_9#originalText","id":"talk.vc.home_bd_suguha_9","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"大家要帮有纪庆生！我会带花过去的。","en":"We're all throwing a birthday party for Yuuki, right? I'm bringing the flowers.","ja":"ユウキさんのお誕生日みんなでお祝いするんだよね! あたしは、お花を持っていくの"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_suguha_11#originalText","id":"talk.vc.home_bd_suguha_11","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"今天是罗妮耶的生日，我打算烤一份加了蜂蜜的派。","en":"I was thinking of baking a pie with honey as a sweetener for Ronie's birthday","ja":"ロニエちゃんの誕生日、蜂蜜を使ったパイを焼いてみようと思うんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_suguha_12#originalText","id":"talk.vc.home_bd_suguha_12","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"今天是缇洁的生日嘛，我去参加女生的聚会啰。男生不准来！","en":"We're having a girls' night out for Tiese's birthday. No boys allowed!","ja":"ティーゼちゃんが誕生日だから女子会してくるね男子は来るの禁止! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_suguha_14#originalText","id":"talk.vc.home_bd_suguha_14","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"今天是莉兹的生日喔。大家要帮她庆祝，你也一起来吧！","en":"It's Liz's birthday today. Come on, let's go wish her a happy birthday.","ja":"リズさんがお誕生日だよほら、みんなでお祝いするから一緒に行こう! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_suguha_15#originalText","id":"talk.vc.home_bd_suguha_15","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"西莉卡的生日我打算送她衣服。一定会很适合她的！","en":"I was thinking of getting Silica a dress for her birthday. I'm sure she'll look adorable!","ja":"シリカちゃんの誕生日に可愛いお洋服を贈ろうと思うんだきっと似合うよね! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_tiese_2#originalText","id":"talk.vc.home_bd_tiese_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"没想到学长会帮我庆生……今天会是我一辈子的回忆。","en":"I'm so honored that you would celebrate my birthday with me. I will cherish this memory, always!","ja":"先輩に誕生日を祝ってもらえるなんて……今日は一生の思い出です"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_tiese_3#originalText","id":"talk.vc.home_bd_tiese_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"听说今天是桐人学长的生日。您会帮他庆祝吗？","en":"I hear it's Kirito's birthday today. Are we having a party?","ja":"今日はキリト先輩の誕生日だそうですねお祝い、されるんですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_tiese_4#originalText","id":"talk.vc.home_bd_tiese_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长，生日快乐。今天就由我来下厨吧！","en":"Happy Birthday, Mentor! I'm preparing you quite a feast today!","ja":"先輩、お誕生日おめでとうございます今日はごちそうを作りますね! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_tiese_5#originalText","id":"talk.vc.home_bd_tiese_5","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天是爱丽丝大人的生日。学长当然也会送她礼物吧？","en":"Today is Lady Alice's birthday, isn't it? You're getting her a gift, I assume?","ja":"今日はアリスさまのお誕生日先輩も、もちろんお祝いの贈り物をされるんですよね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_tiese_6#originalText","id":"talk.vc.home_bd_tiese_6","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"亚丝娜大人的生日……是不是该动员整间学院举办庆生会呢？","en":"The Lady Asuna's birthday... Perhaps we should invite her to a party at the Academy?","ja":"アスナさんのお誕生日……学院を上げて生誕祭をやるべきでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_tiese_7#originalText","id":"talk.vc.home_bd_tiese_7","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天是绿之剑士大人的生日吧。","en":"Today is the green swordswoman's birthday?","ja":"リーファさんは、今日がお誕生日なのですね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_tiese_8#originalText","id":"talk.vc.home_bd_tiese_8","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天好像是诗乃大人的生日。庆祝的规模是否应该要跟索鲁斯大人相同呢？","en":"Today is Lady Sinon's birthday. We should brighten up her day just like Solus’s rays!","ja":"シノンさんのお誕生日だそうですソルス様と同じようにお祝いするのがよいでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_tiese_11#originalText","id":"talk.vc.home_bd_tiese_11","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天是罗妮耶的生日。方便的话，您愿意来一起庆祝吗？","en":"It's Ronie's birthday today. Would you help me throw her a party?","ja":"今日、ロニエが誕生日なんですよろしければ、一緒にお祝いしていただけませんか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuna_17#originalText","id":"talk.vc.home_bd_yuna_17","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"今天是瑛二的生日呢！我要特别为你唱一首原创的生日快乐歌！","en":"Today is Eiji's birthday! To celebrate, let's sing a birthday song for him!","ja":"今日はエイジのお誕生日だねオリジナルのバースデーソング、歌ってあげるんだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_2#originalText","id":"talk.vc.home_bd_yuuki_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"哇，你记得我的生日啊！？我好感激你喔！","en":"Whoa, you remembered my birthday?! I think I need a moment!","ja":"うわあ、誕生日覚えててくれたの!?ボク、感激しちゃうよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_3#originalText","id":"talk.vc.home_bd_yuuki_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"你去帮我告诉桐人，说有纪祝他生日快乐！","en":"Tell Kirito I said happy birthday!","ja":"「誕生日おめでとう」ってキリトに伝えておいて! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_6#originalText","id":"talk.vc.home_bd_yuuki_6","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"就算忘了我的生日，也绝对不能忘记亚丝娜的生日！","en":"I might forget my own birthday, but I'd never forget Asuna's birthday!","ja":"ボクの誕生日は忘れてもアスナの誕生日は絶対に忘れないよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_7#originalText","id":"talk.vc.home_bd_yuuki_7","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"今天是莉法的生日！我们一起去帮她庆祝吧。","en":"It's Leafa's birthday today, eh? Let's throw her a party.","ja":"リーファは今日が誕生日なんだ! 一緒にお祝いに行こうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_8#originalText","id":"talk.vc.home_bd_yuuki_8","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"今天是诗乃的生日呢。不知道她有没有想要的东西？","en":"It's Sinon's birthday today. Do you know what she wants?","ja":"今日はシノンの誕生日なんだねなにか欲しいものあるのかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_14#originalText","id":"talk.vc.home_bd_yuuki_14","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"因为今天是莉兹的生日，所以大家一定都会到吧。我们也过去吧！","en":"Since it's Liz's birthday today, I'm sure the gang is throwing her a party. Let's go too!","ja":"今日はリズの誕生日だからきっとみんな集まってるよねボクたちも行こう! "},"kind":"dialogue"},{"uid":"talk.vc.home_bd_yuuki_15#originalText","id":"talk.vc.home_bd_yuuki_15","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"西莉卡的生日啊……不知道送毕娜爱吃的食物之类的，她会不会开心。","en":"Silica's birthday, eh? Do you think she'd like it if I got Pina's favorite food or something?","ja":"シリカの誕生日かあ……ピナの好きな食べ物とか喜んでもらえるかな? "},"kind":"dialogue"},{"uid":"talk.vc.home_ch_alice_1#originalText","id":"talk.vc.home_ch_alice_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这么说来，我好像没什么为任务飞到北地过。","en":"Come to think of it, I haven't gone north on missions much.","ja":"そういえば任務で北地に飛んだことはあまりなかったような気がします"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_alice_2#originalText","id":"talk.vc.home_ch_alice_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"虽然竞争套路的比赛不具意义……但是，你的剑术挺精彩的。","en":"Comparing forms is rather meaningless... But your sword was rather good.","ja":"型の競い合いなど無意味ですが……お前の剣の型は、なかなかのものでしたね"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_alice_3#originalText","id":"talk.vc.home_ch_alice_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"修剑学院啊……我有些憧憬呢，拥有一起钻研目标的伙伴这件事。","en":"The Swordcraft Academy? The idea has always appealed to me. I would love to have cohorts with whom to study.","ja":"修剣学院ですか……少し憧れます共に研鑽を積む仲間というのは"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_alice_4#originalText","id":"talk.vc.home_ch_alice_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……禁忌目录是绝对的。不过，你的行动……肯定也正确无误。","en":"The Taboo Index is absolute. However...I believe you did the right thing.","ja":"……禁忌目録は絶対ですしかし、お前の行動は……きっと、正しいのですね"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_alice_5#originalText","id":"talk.vc.home_ch_alice_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你居然能打败那个艾尔多利耶，说实话吓了我一跳。看来是我低估你了。","en":"I was honestly surprised when you bested Eldrie. It would seem I underestimated you.","ja":"あのエルドリエを破るとは正直驚きましたお前を侮っていたようです"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_alice_6#originalText","id":"talk.vc.home_ch_alice_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"卡迪娜尔大人跟最高司祭大人身上，似乎有许多我们不知道的秘密呢。","en":"It would seem that Cardinal and the High Pontifex are keeping many secrets from us.","ja":"カーディナル様と最高司祭様には我々の知らない秘密が多く存在するようですね"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_alice_7#originalText","id":"talk.vc.home_ch_alice_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"既打败迪索尔巴德阁下，也不屈服于奸计……我对你的行动力惊叹不已。","en":"You defeated Deusolbert and didn't fall for the scheme... I continue to be awed by your dynamism.","ja":"デュソルバート殿を破り奸計にも負けず……お前の行動力には驚嘆します"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_alice_8#originalText","id":"talk.vc.home_ch_alice_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我多少有对你的招式感到吃惊。不过，你太依赖武器了呢。","en":"Your moves surprised me a little. However, you are too reliant on your weapon.","ja":"お前の技には、少々驚きました。ですが、武器に頼りすぎですね"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_alice_9#originalText","id":"talk.vc.home_ch_alice_9","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"没想到叔叔居然会败北……我直到现在还是难以置信。","en":"I never expected that Uncle would be defeated. Even now, I still cannot believe it.","ja":"まさか小父様が敗れるとは……今でも信じられません"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_alice_10#originalText","id":"talk.vc.home_ch_alice_10","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"如今知道元老院的所作所为，我都不晓得该相信什么才好了。","en":"Now that I have discovered the Prime Senator's scheme... I no longer know whom to trust.","ja":"元老院の所業を知った今何を信じていいのかわからなくなってしまいました"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_alice_11#originalText","id":"talk.vc.home_ch_alice_11","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我要打倒最高司祭大人。这同时，也正是为了我自己！","en":"I will defeat the High Pontifex. Not for anyone but myself!","ja":"私は最高司祭様を倒す誰でもなく、私自身のために! "},"kind":"dialogue"},{"uid":"talk.vc.home_ch_alice_12#originalText","id":"talk.vc.home_ch_alice_12","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我现在仍相信，你是可以为了人们振作起来的。来，拿出勇气吧！","en":"I have faith that you will rise. Come, have courage!","ja":"お前なら、立ち上がってくれると信じていますさあ、勇気を! "},"kind":"dialogue"},{"uid":"talk.vc.home_ch_eugeo_1#originalText","id":"talk.vc.home_ch_eugeo_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"卢利特村……有好的回忆，也有不好的回忆……不过总有一天，我会跟爱丽丝一起回来。","en":"Rulid Village... I have good memories and bad memories there, but I can't wait to go back there someday with Alice.","ja":"ルーリッド村……いい思い出も悪い思い出もあるけど……いつかアリスと帰ってくるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_eugeo_2#originalText","id":"talk.vc.home_ch_eugeo_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"照顾马匹很辛苦呢。但是多亏这件事，我觉得体力变好了。","en":"Taking care of the horses sure was tough. But on the bright side, I think my muscles are stronger for it.","ja":"馬の世話は大変だったねでも、おかげで体力はついた気がする"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_eugeo_3#originalText","id":"talk.vc.home_ch_eugeo_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"没想到我能进入修剑学院，真是作梦都没想到。","en":"I never dreamed I'd be a student at the Swordcraft Academy!","ja":"まさか、自分が修剣学院に入れるなんて夢にも思わなかったよ"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_eugeo_4#originalText","id":"talk.vc.home_ch_eugeo_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"就算受到禁忌目录规范，身为一个人，还是不能对某些事情坐视不管！","en":"Taboo Index or no, as a human being, there are certain acts I can't let slide!","ja":"例え禁忌目録があったとしても人として見過ごせないことがあるんだ! "},"kind":"dialogue"},{"uid":"talk.vc.home_ch_eugeo_5#originalText","id":"talk.vc.home_ch_eugeo_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"艾尔多利耶这个名字……我曾经在哪听过。","en":"Eldrie? I've heard that name before...","ja":"エルドリエっていう名前……どこかで聞いたことがあるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_eugeo_6#originalText","id":"talk.vc.home_ch_eugeo_6","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"没想到能读到这个世界的由来，这座图书馆真是惊人……","en":"I can read about the origins of this world? Wow. What an impressive library.","ja":"この世界の成り立ちが読めるなんて、すごい図書室があるんだね……"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_eugeo_7#originalText","id":"talk.vc.home_ch_eugeo_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"真不愧是集成骑士……不论哪个对手，都不是用一般手段赢得了的。","en":"That's an Integrity Knight, alright. No one stands a chance.","ja":"さすが整合騎士……どの相手も、とても一筋縄では勝てそうにないよ"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_eugeo_8#originalText","id":"talk.vc.home_ch_eugeo_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"集成骑士爱丽丝……真的是那位爱丽丝吗……！？","en":"Integrity Knight Alice... Is she really our Alice?!","ja":"整合騎士アリス……やっぱりあのアリスなのか……!?"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_eugeo_9#originalText","id":"talk.vc.home_ch_eugeo_9","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"就算对手是传说中的英雄，我也不能输……！","en":"Even though I'm up against a hero of legend, I can't let him defeat me!","ja":"たとえ相手が伝説の英雄でも僕は負ける訳にはいかない……! "},"kind":"dialogue"},{"uid":"talk.vc.home_ch_eugeo_10#originalText","id":"talk.vc.home_ch_eugeo_10","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"原来，我一直，在渴求着爱……","en":"I was...searching for love.","ja":"僕は、愛を、求めていたんだ……"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_eugeo_11#originalText","id":"talk.vc.home_ch_eugeo_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"为了守护全世界的人……我们绝不能逃避！","en":"The people of this world need saving... We can't run away and abandon them!","ja":"世界中の人たちを守るために……僕たちは、逃げちゃいけないんだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_eugeo_12#originalText","id":"talk.vc.home_ch_eugeo_12","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"没问题，你可以办到的。我没说错吧？","en":"Don't worry. I know you can do it. And you know it, too.","ja":"大丈夫、君ならできるそうだろう"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_kirito_1#originalText","id":"talk.vc.home_ch_kirito_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"一看到美丽的景色，我就会想起卢利特呢。……真想让你看看。","en":"Seeing the pretty vistas reminds me of Rulid. I wish you could see it...","ja":"美しい景色を見るとルーリッドを思い出すよ……見せたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_kirito_2#originalText","id":"talk.vc.home_ch_kirito_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"用稻草堆成的床可是意外的温暖喔。你要不要试试看？","en":"Straw beds are actually pretty warm. Wanna try it out?","ja":"ワラを積んで作るベッドは意外とあったかいんだぜ試してみるか?"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_kirito_3#originalText","id":"talk.vc.home_ch_kirito_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"发自于内心的意念……《心意》……吗……啊，抱歉，我在想事情。","en":"True will from the heart... \"True will\"...huh... Oh, sorry. Was just doing some thinking.","ja":"心からいずる意志……《シンイ》……か……あ、悪ぃ、考え事してた"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_kirito_4#originalText","id":"talk.vc.home_ch_kirito_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"你就别忘了保持平常心，Stay cool吧。","en":"Don't forget to keep your peace of mind. Let's make \"stay cool\" our mantra.","ja":"平常心は忘れないようにステイ・クールで行こうぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_kirito_5#originalText","id":"talk.vc.home_ch_kirito_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"最近只要一感到迷惘，浏海附近总是会翘起来。你可以帮我看看吗？","en":"Can you look at my bangs for me? Whenever I'm stuck making a decision, I feel a tug on them.","ja":"最近迷うことがあるといつも前髪のあたりがツンツンするんだちょっと見てくれないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_kirito_6#originalText","id":"talk.vc.home_ch_kirito_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不管陷入什么样的困境，都绝对不放弃挣扎。这才像我的作风，对吧？","en":"Even if I'm stuck, going nowhere, I'll never stop struggling to break free. I have to live like my authentic self, you know?","ja":"にっちもさっちもいかなくても悪あがきだけは放棄しないんだその方が俺らしいだろ?"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_kirito_7#originalText","id":"talk.vc.home_ch_kirito_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就算对手是女人，我也不会放水。毕竟我可是数次败在女剑士之下！","en":"I never pull my punches, even against a woman. I've lost to many a powerful swordswoman before.","ja":"俺は相手が女でも手を抜かないんだこれまで何度も女剣士に負けてるからな"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_kirito_8#originalText","id":"talk.vc.home_ch_kirito_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"欸，我的背后有黏着什么吗？……像是蜘蛛之类的。","en":"Hey, is there something on my back? Like, a spider or something?","ja":"なあ、俺の背中に何か付いてないか?……クモっぽい奴とか"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_kirito_9#originalText","id":"talk.vc.home_ch_kirito_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"拍拍口袋就发现有两颗包子。","en":"When I tapped my pocket, I found two buns.","ja":"ポケットを叩けば饅頭がふたつだ"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_kirito_10#originalText","id":"talk.vc.home_ch_kirito_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我觉得，有时候还是只能透过剑来交谈。……你愿意接下我的剑吗？","en":"Some feelings can only be communicated through the sword... So, will you listen to my sword?","ja":"剣でしか語り合えないことってあると思うんだ……俺の剣を、受けてくれるか?"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_kirito_11#originalText","id":"talk.vc.home_ch_kirito_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"太见外了！不要对我有所隐瞒啦。","en":"Hey, why'd you hide that from me? I thought we were friends!","ja":"水臭いぞ!俺に隠し事なんてするなよな"},"kind":"dialogue"},{"uid":"talk.vc.home_ch_kirito_12#originalText","id":"talk.vc.home_ch_kirito_12","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"回忆永远都会在这里。","en":"My memories live on inside of me, forever.","ja":"思い出は、永遠に、ここにある"},"kind":"dialogue"},{"uid":"talk.vc.home_day_administrator_11#originalText","id":"talk.vc.home_day_administrator_11","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"如果身为普通的人民，就是开始工作的日子呢。目录上也有这么记载。","en":"Today is the start of the work-week for ordinary civilians. I will catalogue that.","ja":"普通の民であれば働き始める日ね目録にも記してある"},"kind":"dialogue"},{"uid":"talk.vc.home_day_administrator_12#originalText","id":"talk.vc.home_day_administrator_12","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"勤勉是好事喔，我可爱的人偶。","en":"Diligence is a virtue, my sweet little doll.","ja":"勤勉なのはいいことよ私のかわいいお人形さん"},"kind":"dialogue"},{"uid":"talk.vc.home_day_administrator_13#originalText","id":"talk.vc.home_day_administrator_13","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"安息日……你偶尔也可以休息一下无妨。","en":"A day of rest... Yes, perhaps you should rest sometimes.","ja":"安息日……たまにはあなたも休むといいわ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_administrator_14#originalText","id":"talk.vc.home_day_administrator_14","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"我会好好帮你重新调整的。没问题，你不用害怕。","en":"I will carefully readjust you. Don't worry. There's nothing to fear.","ja":"再調整、しっかりしてあげるわね大丈夫よ、怖くないから"},"kind":"dialogue"},{"uid":"talk.vc.home_day_agil_11#originalText","id":"talk.vc.home_day_agil_11","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"星期一没什么客人上门，我干脆来盘点好了。","en":"Customer turnout is always pretty meh on Mondays. Maybe I should take inventory or something.","ja":"月曜は客の入りがイマイチだ棚卸しでもするかな"},"kind":"dialogue"}]};
